import { readFileSync, writeFileSync, existsSync, readdirSync } from 'node:fs';
import { join } from 'node:path';
const lock = JSON.parse(readFileSync('package-lock.json', 'utf8'));
const allowed = new Set([
  'MIT',
  'Apache-2.0',
  'Apache 2.0',
  'Apache2',
  'BSD-2-Clause',
  'BSD-3-Clause',
  'ISC',
  'BlueOak-1.0.0',
  '0BSD',
  'Unlicense',
  'MPL-2.0',
]);
const rows = [];
let notices =
  '# Third-party runtime notices\n\nGenerated by `npm run licenses` from the lockfile and installed packages.\nOriginal bridge code is MIT; dependencies retain their own licenses.\nOpenRGB and Node.js are installed separately and are not distributed here.\n\n';
for (const [path, entry] of Object.entries(lock.packages)) {
  if (!path) continue;
  let pkg;
  if (existsSync(join(path, 'package.json')))
    pkg = JSON.parse(readFileSync(join(path, 'package.json'), 'utf8'));
  const raw =
    entry.license ?? pkg?.license ?? pkg?.licenses?.map((x) => x.type);
  const licenses = Array.isArray(raw)
    ? raw
    : [typeof raw === 'object' ? raw.type : raw];
  if (licenses.some((x) => !allowed.has(x)))
    throw new Error(`Unreviewed license: ${path} ${JSON.stringify(raw)}`);
  if (entry.dev) continue;
  if (!pkg) throw new Error(`Runtime package missing: ${path}`);
  const files = readdirSync(path)
    .filter((x) => /^(licen[sc]e|copying|notice)(\.|$|-)/i.test(x))
    .sort();
  if (!files.length) throw new Error(`Missing runtime license text: ${path}`);
  rows.push(`| ${pkg.name} | ${pkg.version} | ${licenses.join(' OR ')} |`);
  notices += `## ${pkg.name} ${pkg.version}\n\n`;
  for (const f of files)
    notices += `### ${f}\n\n\`\`\`text\n${readFileSync(join(path, f), 'utf8')}\n\`\`\`\n\n`;
  if (pkg.name === 'qrcode-terminal')
    notices +=
      'The included vendor/QRCode implementation is Copyright (c) 2009 Kazuhiko Arase, under the MIT license (https://opensource.org/license/mit). Its source license header is retained in the installed package. The MIT permission and disclaimer text appears in this repository LICENSE.\n\n';
}
writeFileSync('THIRD_PARTY_NOTICES.md', notices);
writeFileSync(
  'docs/dependency-licenses.md',
  '# Dependency license review\n\nRuntime dependency inventory generated from the exact lockfile. These permissive licenses permit use with the MIT original code, with upstream notices retained. No OpenRGB binaries, drivers, Node runtime or manufacturer SDKs are redistributed. The independent TCP adapter communicates with separately installed OpenRGB; it contains no copied OpenRGB implementation. Development-only Lightning CSS packages use MPL-2.0 and are neither modified nor included in the preview archive. Re-run this review when dependencies change. This inventory is an engineering review, not a legal opinion.\n\n| Package | Version | License |\n| --- | --- | --- |\n' +
    rows.join('\n') +
    '\n\nFull runtime notices: [THIRD_PARTY_NOTICES.md](../THIRD_PARTY_NOTICES.md).\n',
);
console.log(
  `Reviewed ${Object.keys(lock.packages).length - 1} locked packages; ${rows.length} runtime notices retained.`,
);
